// UpdateGuildModule operation middleware
func (sh *strictHandler) UpdateGuildModule(w http.ResponseWriter, r *http.Request, guildId GuildId, moduleId string) {
	var request UpdateGuildModuleRequestObject

	request.GuildId = guildId
	request.ModuleId = moduleId

	var body UpdateGuildModuleJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error) {
		return sh.ssi.UpdateGuildModule(ctx, request.(UpdateGuildModuleRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "UpdateGuildModule")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(UpdateGuildModuleResponseObject); ok {
		if err := validResponse.VisitUpdateGuildModuleResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

